CREATE TABLE IF NOT EXISTS sc_users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sc_settings(name VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sc_content(id INT AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(20) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,image VARCHAR(255) NOT NULL DEFAULT '',link VARCHAR(500) NOT NULL DEFAULT '',published TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sc_cases(id INT AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(30) NOT NULL UNIQUE,secret_hash VARCHAR(64) NOT NULL,kind VARCHAR(20) NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,unit VARCHAR(80) NOT NULL,body TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'Recibida',response TEXT NULL,consent_version VARCHAR(30) NOT NULL,consent_text TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sc_audit(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(80) NOT NULL,target_id INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sc_limits(bucket VARCHAR(64) PRIMARY KEY,hits INT NOT NULL,created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
